package util;import jakarta.servlet.*;import jakarta.servlet.annotation.*;import jakarta.servlet.http.*;import java.io.*;import model.*;
@WebFilter("/*") public class AuthFilter5 implements Filter{public void doFilter(ServletRequest req,ServletResponse res,FilterChain chain)throws IOException,ServletException{HttpServletRequest r=(HttpServletRequest)req;HttpServletResponse p=(HttpServletResponse)res;r.setCharacterEncoding("UTF-8");p.setCharacterEncoding("UTF-8");String u=r.getRequestURI();if(u.contains("/view/management/")||u.contains("/view/customer/")){Object user=r.getSession().getAttribute("user");if(user==null){p.sendRedirect(r.getContextPath()+"/login.jsp");return;}if((u.contains("/management/")&&!(user instanceof ManagementStaff5))||(u.contains("/customer/")&&!(user instanceof Customer5))){p.sendError(403);return;}}chain.doFilter(req,res);}}
